What is the output of this program?

#include <iostream>
using namespace std;
int hits = 0;
void level(int n) {
    try {
        if (n == 0) throw 1;
        level(n - 1);
    } catch (int &e) { hits++; e *= 2; throw; }
}
int main() {
    try { level(2); }
    catch (int e) { cout << hits << " " << e; }
}
